import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { 
  Users, 
  Search, 
  Edit2, 
  Save, 
  X, 
  Lock, 
  Upload, 
  Mail, 
  ShieldCheck,
  Filter,
  MoreVertical,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { getPartyEmails, updatePartyEmail, uploadPartyEmails } from '../services/api';
import { useDropzone } from 'react-dropzone';

export default function PartyManagement() {
  const [parties, setParties] = useState([]);
  const [fetching, setFetching] = useState(true);
  const [search, setSearch] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [editValue, setEditValue] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showBulkUpload, setShowBulkUpload] = useState(false);
  const [bulkFile, setBulkFile] = useState(null);
  const [bulkPassword, setBulkPassword] = useState('');
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    loadParties();
  }, []);

  const loadParties = async () => {
    setFetching(true);
    try {
      const res = await getPartyEmails();
      setParties(res.data.data || []);
    } catch {
      toast.error('Failed to sync with party registry');
    } finally {
      setFetching(false);
    }
  };

  const startEdit = (party) => {
    setEditingId(party._id);
    setEditValue(party.email || '');
    setConfirmPassword('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditValue('');
  };

  const saveEmail = async (id, partyCode) => {
    if (!confirmPassword) return toast.error('Security confirmation required');
    try {
      await updatePartyEmail(id, editValue, confirmPassword);
      toast.success(`Encrypted update successful for ${partyCode}`);
      setParties(p => p.map(item => item._id === id ? { ...item, email: editValue } : item));
      setEditingId(null);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Unauthorized or server error');
    }
  };

  const onDropBulk = (accepted) => {
    if (accepted.length) setBulkFile(accepted[0]);
  };

  const { getRootProps, getInputProps } = useDropzone({
    onDrop: onDropBulk,
    accept: { 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'] },
    maxFiles: 1
  });

  const handleBulkSubmit = async () => {
    if (!bulkFile || !bulkPassword) return toast.error('Missing credentials or file');
    setUploading(true);
    try {
      await uploadPartyEmails(bulkFile, bulkPassword);
      toast.success('Registry updated successfully');
      setShowBulkUpload(false);
      loadParties();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Bulk update failed');
    } finally {
      setUploading(false);
    }
  };

  const filteredParties = parties.filter(p => 
    p.partyCode.toLowerCase().includes(search.toLowerCase()) ||
    p.partyName.toLowerCase().includes(search.toLowerCase()) ||
    (p.email && p.email.toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Identity Management</h1>
          <p className="text-slate-500 text-sm mt-1">Manage entity communication mappings and secure SMTP routing.</p>
        </div>
        <button 
          onClick={() => setShowBulkUpload(true)}
          className="btn-primary flex items-center gap-2"
        >
          <Upload size={18} />
          Bulk Registry Import
        </button>
      </div>

      <div className="flex items-center gap-4 bg-white p-4 rounded-xl border border-slate-200 card-shadow">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Filter by code, name, or contact email..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-slate-50 border-transparent focus:bg-white focus:border-primary-500 focus:ring-4 focus:ring-primary-100 rounded-xl text-sm transition-all outline-none"
          />
        </div>
        <button className="btn-secondary hidden sm:flex items-center gap-2">
          <Filter size={18} />
          Advanced Filter
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 card-shadow overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Entity Signature</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Communication Channel</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-widest">Status</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-widest text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {fetching ? (
                <tr>
                  <td colSpan="4" className="px-6 py-20 text-center">
                    <div className="flex flex-col items-center gap-3">
                      <div className="w-10 h-10 border-4 border-slate-100 border-t-primary-600 rounded-full animate-spin" />
                      <span className="text-sm font-medium text-slate-400">Syncing with Registry...</span>
                    </div>
                  </td>
                </tr>
              ) : filteredParties.length === 0 ? (
                <tr>
                  <td colSpan="4" className="px-6 py-20 text-center text-slate-400 font-medium">
                    No identities found matching the current filter.
                  </td>
                </tr>
              ) : filteredParties.map(p => (
                <tr key={p._id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="text-sm font-bold text-slate-900">{p.partyCode}</div>
                    <div className="text-[11px] font-medium text-slate-500 truncate max-w-[200px]">{p.partyName}</div>
                  </td>
                  <td className="px-6 py-4">
                    {editingId === p._id ? (
                      <div className="flex flex-col gap-2 max-w-sm">
                        <div className="relative">
                          <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                          <input 
                            value={editValue}
                            onChange={e => setEditValue(e.target.value)}
                            className="w-full pl-9 pr-3 py-1.5 text-xs bg-white border border-primary-300 rounded-lg focus:ring-4 focus:ring-primary-50 outline-none"
                            placeholder="comma, separated@emails.com"
                          />
                        </div>
                        <div className="relative">
                          <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                          <input 
                            type="password"
                            value={confirmPassword}
                            onChange={e => setConfirmPassword(e.target.value)}
                            className="w-full pl-9 pr-3 py-1.5 text-xs bg-white border border-primary-300 rounded-lg focus:ring-4 focus:ring-primary-50 outline-none"
                            placeholder="Admin Password"
                          />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-wrap gap-1">
                        {p.email ? p.email.split(',').map((m, i) => (
                          <span key={i} className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 border border-slate-200">
                            {m.trim()}
                          </span>
                        )) : <span className="text-xs text-slate-400 italic">No channel mapped</span>}
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    {p.email ? (
                      <span className="flex items-center gap-1.5 text-[10px] font-bold text-green-600 bg-green-50 px-2 py-1 rounded-md border border-green-100 w-fit">
                        <CheckCircle2 size={12} /> VERIFIED
                      </span>
                    ) : (
                      <span className="flex items-center gap-1.5 text-[10px] font-bold text-red-600 bg-red-50 px-2 py-1 rounded-md border border-red-100 w-fit">
                        <AlertCircle size={12} /> NO ROUTE
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    {editingId === p._id ? (
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => saveEmail(p._id, p.partyCode)}
                          className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                        >
                          <Save size={18} />
                        </button>
                        <button 
                          onClick={cancelEdit}
                          className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-lg transition-colors"
                        >
                          <X size={18} />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => startEdit(p)}
                        className="p-2 text-slate-400 hover:text-primary-600 hover:bg-primary-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                      >
                        <Edit2 size={18} />
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Bulk Upload Modal */}
      {showBulkUpload && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                <ShieldCheck className="text-primary-600" size={24} />
                Bulk Registry Import
              </h3>
              <button onClick={() => setShowBulkUpload(false)} className="text-slate-400 hover:text-slate-900">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 space-y-6">
              <div 
                {...getRootProps()}
                className={cn(
                  "border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all",
                  bulkFile ? "border-green-400 bg-green-50" : "border-slate-200 hover:border-primary-400 bg-slate-50"
                )}
              >
                <input {...getInputProps()} />
                <div className="flex flex-col items-center gap-2">
                  <Upload size={32} className={bulkFile ? "text-green-600" : "text-slate-400"} />
                  <span className="text-sm font-bold text-slate-900">{bulkFile ? bulkFile.name : 'Select Registry File (.XLSX)'}</span>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Authentication Key</label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="password"
                    placeholder="Global Admin Password"
                    value={bulkPassword}
                    onChange={e => setBulkPassword(e.target.value)}
                    className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-primary-500 focus:ring-4 focus:ring-primary-100 rounded-xl text-sm transition-all outline-none"
                  />
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button 
                  onClick={() => setShowBulkUpload(false)}
                  className="flex-1 btn-secondary"
                >
                  Discard
                </button>
                <button 
                  disabled={!bulkFile || !bulkPassword || uploading}
                  onClick={handleBulkSubmit}
                  className="flex-1 btn-primary"
                >
                  {uploading ? 'Processing...' : 'Commit Pipeline'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
